  const seen = new Set(items.map(item => urlKey(item.url)));
  for (const item of data.updates) {
    const key = urlKey(item.url);
    if (seen.has(key)) continue;
    seen.add(key);
    items.push(item);
  }
  const categories = [...new Set([...data.categories, ...items.map(item => item.cat)])];
